import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { dashboardAPI, authAPI } from '../services/api';
import ImageWithFallback from '../components/ImageWithFallback';

const ProfilePage = () => {
  const { user, balance } = useAuth();
  const [stats, setStats] = useState({
    casesOpened: 0,
    upgradesPerformed: 0,
    successRate: 0,
    inventoryValue: 0,
    bestDrop: 'None'
  });
  const [loading, setLoading] = useState(true);
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarMessage, setAvatarMessage] = useState('');


  const handleAvatarChange = (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      setAvatarMessage('Choisis une image JPG, PNG ou WEBP.');
      return;
    }
    setAvatarSaving(true);
    setAvatarMessage('');
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = async () => {
        const size = 256;
        const canvas = document.createElement('canvas');
        canvas.width = size; canvas.height = size;
        const ctx = canvas.getContext('2d');
        const scale = Math.max(size / img.width, size / img.height);
        const w = img.width * scale, h = img.height * scale;
        ctx.drawImage(img, (size - w) / 2, (size - h) / 2, w, h);
        const avatarUrl = canvas.toDataURL('image/webp', 0.82);
        try {
          const response = await authAPI.updateAvatar(avatarUrl);
          localStorage.setItem('wellcase_avatar_url', response.data.avatar_url || '');
          window.location.reload();
        } catch (error) {
          setAvatarMessage(error.response?.data?.detail || 'Impossible de mettre à jour la PP.');
          setAvatarSaving(false);
        }
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  };

  useEffect(() => {
    const fetchProfileData = async () => {
      try {
        // Get user stats from dashboard API
        const statsResponse = await dashboardAPI.getHistory(); // Using history to calculate stats
        const history = statsResponse.data;

        // Calculate stats
        const casesOpened = history.filter(item => item.type === 'opening').length;
        const upgradesPerformed = history.filter(item => item.type === 'upgrade').length;
        const totalActions = casesOpened + upgradesPerformed;
        const successRate = totalActions > 0 ? Math.round((casesOpened / totalActions) * 100) : 0;

        // For demo purposes, we'll set some values
        setStats({
          casesOpened,
          upgradesPerformed,
          successRate,
          inventoryValue: 0, // Would calculate from inventory in real app
          bestDrop: 'AK-47 | Redline (Field-Tested)' // Would find from history
        });
      } catch (error) {
        console.error('Error fetching profile data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchProfileData();
  }, [user]);

  if (loading) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <h1 className="mb-4 gradient-text">Profile</h1>
      <div className="row mb-4">
        <div className="col-md-8">
          <h2>Balance: <span className="text-success">{balance.toLocaleString()} €</span></h2>
        </div>
      </div>

      {/* Profile Header */}
      <div className="row mb-5">
        <div className="col-md-4">
          <div className="text-center">
            <div className="position-relative">
              <ImageWithFallback
                   src={user?.avatar_url || "/images/avatars/default.png"}
                   alt="Avatar"
                   className="rounded-circle mb-3"
                   style={{ width: '120px', height: '120px', objectFit: 'cover' }}
              />
              <div className="position-absolute bottom-0 end-0 bg-success p-1 rounded-circle border border-white">
                <i className="bi bi-check-circle fs-6"></i>
              </div>
            </div>
            <label className="btn btn-outline-light btn-sm mt-2">
              {avatarSaving ? 'Enregistrement…' : 'Changer ma PP'}
              <input type="file" accept="image/*" hidden onChange={handleAvatarChange} disabled={avatarSaving} />
            </label>
            {avatarMessage && <div className="small text-danger mt-2">{avatarMessage}</div>}
            <h4>{user?.username || 'Player'}</h4>
            <p className="text-muted mb-0">Level 1</p>
            <div className="progress mt-3" style={{ height: '10px' }}>
              <div className="progress-bar bg-gradient" role="progressbar" style={{ width: '65%' }}></div>
            </div>
            <small className="text-muted">65% to Level 2</small>
          </div>
        </div>
        <div className="col-md-8">
          <div className="row">
            <div className="col-md-3">
              <div className="card text-center py-4">
                <div className="mb-3">
                  <i className="bi bi-box-display display-4 text-info"></i>
                </div>
                <h5>{stats.casesOpened}</h5>
                <p className="text-muted mb-0">Cases Opened</p>
              </div>
            </div>
            <div className="col-md-3">
              <div className="card text-center py-4">
                <div className="mb-3">
                  <i className="bi bi-arrow-repeat display-4 text-warning"></i>
                </div>
                <h5>{stats.upgradesPerformed}</h5>
                <p className="text-muted mb-0">Upgrades</p>
              </div>
            </div>
            <div className="col-md-3">
              <div className="card text-center py-4">
                <div className="mb-3">
                  <i className="bi bi-graph-up display-4 text-success"></i>
                </div>
                <h5>{stats.successRate}%</h5>
                <p className="text-muted mb-0">Success Rate</p>
              </div>
            </div>
            <div className="col-md-3">
              <div className="card text-center py-4">
                <div className="mb-3">
                  <i className="bi bi-gem display-4 text-danger"></i>
                </div>
                <h5>€{stats.inventoryValue}</h5>
                <p className="text-muted mb-0">Inventory Value</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Best Drop */}
      <div className="row mb-5">
        <div className="col-12">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Best Drop</h5>
            </div>
            <div className="card-body text-center">
              {stats.bestDrop !== 'None' ? (
                <>
                  <div className="mb-3">
                    <ImageWithFallback
                         src="/images/items/ak47_redline.png"
                         alt="Best Drop"
                         className="img-fluid"
                         style={{ maxWidth: '200px', maxHeight: '150px' }}
                    />
                  </div>
                  <h4 className="gradient-text">{stats.bestDrop}</h4>
                  <p className="text-muted">Your most valuable item</p>
                </>
              ) : (
                <p className="text-muted py-4">No items yet</p>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Recent Activity */}
      <div className="row">
        <div className="col-12">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Recent Activity</h5>
            </div>
            <div className="card-body">
              <div className="table-responsive">
                <table className="table table-hover align-middle mb-0">
                  <thead className="table-dark">
                    <tr>
                      <th>Time</th>
                      <th>Activity</th>
                      <th>Reward</th>
                    </tr>
                  </thead>
                  <tbody>
                    {/* In a real app, we'd map through recent history */}
                    <tr>
                      <td>Just now</td>
                      <td>Opened Case</td>
                      <td><span className="badge bg-success">+50 €</span></td>
                    </tr>
                    <tr>
                      <td>2 hours ago</td>
                      <td>Daily Reward Claimed</td>
                      <td><span className="badge bg-info">+100 €</span></td>
                    </tr>
                    <tr>
                      <td>Yesterday</td>
                      <td>Upgrade Attempt</td>
                      <td><span className="badge bg-secondary">Failed</span></td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProfilePage;
